            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            out.append(cells)
    return out


def _canonical(cells):
    pts = list(cells)
    forms = []
    for k in range(8):
        transformed = []
        for y, x in pts:
            if k < 4:
                a, b = y, x
            else:
                a, b = y, -x
            for _ in range(k % 4):
                a, b = b, -a
            transformed.append((a, b))
        min_y = min(y for y, x in transformed)
        min_x = min(x for y, x in transformed)
        forms.append(tuple(sorted((y - min_y, x - min_x) for y, x in transformed)))
    return min(forms)


def transform(grid):
